INSERT INTO seasons(id,code,name,starts_on,ends_on,is_current) VALUES('39800000-0000-0000-0000-000000000100','WEEK_SYN','Época semanal sintética',CURRENT_DATE-30,CURRENT_DATE+60,true);
INSERT INTO user_memberships(id,user_id,season_id,programme_id,starts_on) SELECT ('39800000-0000-0000-0000-'||lpad((n+100)::text,12,'0'))::uuid,('39800000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'39800000-0000-0000-0000-000000000100',p.id,CURRENT_DATE-20 FROM programmes p CROSS JOIN unnest(ARRAY[11,12]) n WHERE code='Leisure';
INSERT INTO training_group_members(group_id,membership_id,added_by_id) SELECT '39800000-0000-0000-0000-000000000200',id,'39800000-0000-0000-0000-000000000001' FROM user_memberships;
INSERT INTO training_plans(id,title,programme_id,training_group_id,season_id,week_start,created_by_id)
SELECT ('39800000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,title,p.id,('39800000-0000-0000-0000-'||lpad(g::text,12,'0'))::uuid,'39800000-0000-0000-0000-000000000100',date_trunc('week',CURRENT_DATE)::date+offset_days,'39800000-0000-0000-0000-000000000001'
FROM programmes p CROSS JOIN(VALUES(300,'Semana forma A',200,0,'Leisure'),(301,'Semana forma B',200,7,'Leisure'),(302,'Semana reservada',201,0,'Initiation')) f(n,title,g,offset_days,code2) WHERE code=code2;
INSERT INTO training_sessions(id,plan_id,title,starts_at,ends_at,entry_kind,created_by_id)
SELECT ('39800000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('39800000-0000-0000-0000-'||lpad(plan::text,12,'0'))::uuid,title,(date_trunc('week',CURRENT_DATE)::date+day+start_time) AT TIME ZONE 'Europe/Lisbon',(date_trunc('week',CURRENT_DATE)::date+day+end_time) AT TIME ZONE 'Europe/Lisbon',kind::training_entry_kind,'39800000-0000-0000-0000-000000000001'
FROM(VALUES(400,300,'Água tarde alfa',0,time '16:10',time '17:00','TRAINING'),(401,300,'Ginásio tarde beta',0,time '18:20',time '19:05','TRAINING'),(402,300,'Sábado água sintética',5,time '10:30',time '11:20','TRAINING'),(403,300,'Descanso explícito sintético',0,time '07:15',time '07:30','REST'),(404,300,'Sessão cancelada sintética',1,time '15:00',time '15:45','TRAINING'),(405,301,'Manhã alternativa sintética',8,time '07:05',time '07:35','TRAINING'),(406,301,'Tarde alternativa sintética',9,time '16:00',time '16:45','TRAINING'),(407,301,'Complemento alternativo sintético',11,time '18:00',time '18:40','TRAINING'),(408,302,'Conteúdo privado reservado',0,time '09:00',time '09:30','TRAINING')) f(n,plan,title,day,start_time,end_time,kind);
UPDATE training_sessions SET status='CANCELLED',cancelled_at=now(),cancelled_by_id='39800000-0000-0000-0000-000000000001',cancellation_reason='Cancelamento de fixture sintética' WHERE id='39800000-0000-0000-0000-000000000404';
INSERT INTO training_session_segments(id,session_id,position,modality,title) VALUES ('39800000-0000-0000-0000-000000000500','39800000-0000-0000-0000-000000000400',1,'WATER','Água sintética'),('39800000-0000-0000-0000-000000000501','39800000-0000-0000-0000-000000000401',1,'GYM','Ginásio sintético');
